   SELECT id INTO v_id FROM catalogue_produits WHERE categorie='pac_air_eau' AND marque='De Dietrich' AND (reference=p->>'reference' OR (NULLIF(p->'caracteristiques'->>'reference_fabricant','') IS NOT NULL AND reference ILIKE '%' || (p->'caracteristiques'->>'reference_fabricant') || '%')) ORDER BY CASE WHEN reference=p->>'reference' THEN 0 ELSE 1 END, created_at LIMIT 1;
   IF v_id IS NULL THEN
     INSERT INTO catalogue_produits (entreprise_id,categorie,nom,marque,reference,description,caracteristiques,prix_unitaire_ht,unite,tva_taux,eligible_mpr,eligible_cee,fiche_cee,actif,public_cible,catalogue_groupe,forfait_pose_ht,forfait_evacuation_ht)
     VALUES (v_entreprise,'pac_air_eau',p->>'nom','De Dietrich',p->>'reference',p->>'description',p->'caracteristiques',(p->>'prix_unitaire_ht')::numeric,'unite',5.5,true,true,'BAR-TH-171',true,'particulier','particulier',0,0);
   ELSE
     UPDATE catalogue_produits SET nom=p->>'nom', marque='De Dietrich', reference=p->>'reference', description=p->>'description',
       caracteristiques=(COALESCE(caracteristiques,'{}'::jsonb) - 'source_tarifs' - 'source_date') || COALESCE(p->'caracteristiques','{}'::jsonb),
       prix_unitaire_ht=(p->>'prix_unitaire_ht')::numeric, tva_taux=5.5, fiche_cee='BAR-TH-171', eligible_cee=true, eligible_mpr=true,
       actif=true, public_cible='particulier', catalogue_groupe='particulier'
     WHERE id=v_id;
     -- Forfaits de pose et d'évacuation existants préservés.
   END IF;
   v_id := NULL;
 END LOOP;
